        {
          type: "message.dispatch",
          commandId: command.commandId,
          threadId: command.threadId,
          messageId: wake.messageId,
          text: wake.text,
          notification: wake.notification,
          attachments: [],
          dispatchMode: { type: "queue_after_active" },
          createdBy: "agent",
          creationSource: "server",
