      const { turnItems } = yield* projectionStore
        .getThreadRecords(input.threadId, ["turnItems"], {
          turnItemTypes: ["link_request"],
          turnItemStatuses: ["waiting"],
          messageRoles: [],
        })
        .pipe(mapDispatchError(input.command));
