    "Orchestrator.dispatchRuntimeRequestDeliveryReceipt",
  )(function* (
    command: Extract<
      OrchestrationV2InternalCommand,
      { readonly type: "runtime-request.delivery.fail" | "runtime-request.delivery.confirm" }
